"""Migrated Meridian CRM 4.2 opportunity_pipeline workflow."""

from typing import Any


def _is_positive_amount(value: Any) -> bool:
    """Implement NVL(AMT,0) > 0 for the source workflow guard."""
    if value is None or value == "":
        value = 0
    try:
        return float(value) > 0
    except (TypeError, ValueError):
        return False


def _has_lost_reason(record: dict) -> bool:
    """Implement LOST_RSN <> '' with missing fields reading as empty strings."""
    return isinstance(record.get("LOST_RSN", ""), str) and record.get("LOST_RSN", "") != ""


def fire(state: str, event: str, record: dict) -> dict:
    """Fire the first document-order matching opportunity pipeline transition."""
    new_record = dict(record)

    matched = False
    next_state = state
    actions: tuple[tuple[str, str, str], ...] = ()

    # Transitions are deliberately evaluated in legacy XML document order.
    if state == "P" and event == "qualify" and _is_positive_amount(record.get("AMT", "")):
        matched = True
        next_state = "Q"
        actions = (
            ("set", "STAGE_PCT", "25"),
            ("audit", "OPP_QUAL", ""),
        )
    elif state == "Q" and event == "advance":
        matched = True
        next_state = "N"
        actions = (("set", "STAGE_PCT", "60"),)
    elif (
        state == "N"
        and event == "close_won"
        and record.get("CLOSE_DT", "") != "00000000"
    ):
        matched = True
        next_state = "W"
        actions = (
            ("set", "STAGE_PCT", "100"),
            ("audit", "OPP_WON", ""),
            ("notify", "won_deal", ""),
        )
    elif state == "P" and event == "close_lost" and _has_lost_reason(record):
        matched = True
        next_state = "L"
        actions = (
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST", ""),
        )
    elif state == "Q" and event == "close_lost" and _has_lost_reason(record):
        matched = True
        next_state = "L"
        actions = (
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST", ""),
        )
    elif state == "N" and event == "close_lost" and _has_lost_reason(record):
        matched = True
        next_state = "L"
        actions = (
            ("set", "STAGE_PCT", "0"),
            ("audit", "OPP_LOST", ""),
        )

    if not matched:
        return {
            "state": state,
            "record": new_record,
            "audits": ["WF_NOMATCH"],
            "notifies": [],
            "matched": False,
        }

    audits: list[str] = []
    notifies: list[str] = []
    for action_type, value, _unused in actions:
        if action_type == "set":
            new_record[value] = _unused
        elif action_type == "audit":
            audits.append(value)
        elif action_type == "notify":
            notifies.append(value)

    return {
        "state": next_state,
        "record": new_record,
        "audits": audits,
        "notifies": notifies,
        "matched": True,
    }
